const $ = (s, root = document) => root.querySelector(s);
const esc = (v = "") => String(v).replace(/[&<>"']/g, c => ({ "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#39;" }[c]));
const uid = (() => { let id = localStorage.getItem("study-helper-uid"); if (!id) { id = crypto.randomUUID?.() || `${Date.now()}-${Math.random()}`; localStorage.setItem("study-helper-uid", id); } return id; })();
const state = { quizzes:[], sets:[], mistakes:[], view:location.pathname === "/qna" ? "qna" : location.pathname === "/practice" ? "review" : "home", sidebarCollapsed:localStorage.getItem("studyroom-sidebar-collapsed")==="true", modal:null, quiz:null, qi:0, selected:null, quizWrong:[], qna:null, qIndex:0, qResult:null, qnaMode:"text", quizMode:"text", qnaDraft:[] };
state.editingSet=null;state.editQuestions=[];
const api = async (path, options = {}) => { const headers = { ...(options.body instanceof FormData ? {} : {"Content-Type":"application/json"}), ...(options.headers || {}) }; if (path.startsWith("/api/v1/mistakes") || path.startsWith("/api/v1/qna") || path.includes("/attempts")) headers["x-user-id"] = uid; const response = await fetch(path, { ...options, headers }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.message || data.error || `Request failed (${response.status})`); return data.data; };
const toast = (message, error = false) => { document.querySelector(".toast")?.remove(); const node = document.createElement("div"); node.className = `toast${error ? " error" : ""}`; node.textContent = message; document.body.append(node); setTimeout(() => node.remove(), 3200); };
const refresh = async () => { const results = await Promise.allSettled([api("/api/v1/quiz"), api("/api/v1/qna"), api("/api/v1/mistakes", {headers:{"x-user-id":uid}})]); state.quizzes = results[0].status === "fulfilled" ? results[0].value || [] : []; state.sets = results[1].status === "fulfilled" ? results[1].value || [] : []; state.mistakes = results[2].status === "fulfilled" ? results[2].value || [] : []; render(); };
const navItem = (view, href, icon, label) => `<a class="${state.view === view ? "active" : ""}" href="${href}" data-view="${view}" title="${label}"><span class="nav-icon">${icon}</span>${label}</a>`;
function shell(content) { const label = state.view === "home" ? "Overview" : state.view === "qna" ? "Open response" : "Review mistakes"; return `<div class="shell ${state.sidebarCollapsed?"sidebar-collapsed":""}"><aside class="sidebar"><div class="brand"><button class="brand-mark sidebar-toggle" data-action="toggle-sidebar" aria-label="${state.sidebarCollapsed?"Expand":"Collapse"} sidebar" title="${state.sidebarCollapsed?"Expand":"Collapse"} sidebar" style="background:#173e32;color:#c8ed8c;border:0">${state.sidebarCollapsed?"⇥":"☰"}</button>studyroom</div><div class="side-label">Your workspace</div><nav class="nav">${navItem("home","/","⌂","Overview")}${navItem("qna","/qna","▤","Q&A practice")}${navItem("review","/practice","↻","Review mistakes")}</nav><div class="side-bottom">A little progress, every day.<div class="profile"><span class="avatar">S</span><span>My study space</span></div></div></aside><main class="main"><div class="topbar"><div class="crumb">Studyroom <span class="muted">/</span> <strong>${label}</strong></div><div class="top-actions"><span class="date">${new Date().toLocaleDateString(undefined,{weekday:"short",month:"short",day:"numeric"})}</span><button class="btn light small" data-action="refresh">↻ Refresh</button></div></div><div class="content">${content}</div></main><nav class="mobile-nav"><a class="${state.view === "home" ? "active" : ""}" href="/" data-view="home"><span>⌂</span>Home</a><a class="${state.view === "qna" ? "active" : ""}" href="/qna" data-view="qna"><span>▤</span>Q&A</a><a class="${state.view === "review" ? "active" : ""}" href="/practice" data-view="review"><span>↻</span>Review</a></nav></div>${state.modal ? modalMarkup() : ""}`; }
function card(item, type, index) { const q = type === "quiz", title = item.title || "Untitled set", count = (q ? item.quizes : item.questions)?.length || 0; return `<article class="study-card"><div class="card-top"><span class="tag ${q ? "" : "purple"}">${q ? "✦ Multiple choice" : "▤ Open response"}</span><span class="card-menu">${esc(item.subject || "General")}</span></div><h3>${esc(title)}</h3><p>${count} questions · ${esc(item.subject || "No subject")}</p><div class="card-foot"><span class="card-meta">${q ? "QUIZ" : "Q&A SET"} · ${String(item._id || "").slice(-6).toUpperCase()}</span><div class="card-actions"><button class="btn small" data-action="${q ? "start-quiz" : "start-qna"}" data-id="${esc(item._id)}">Practice</button>${q ? "" : `<button class="btn light small" data-action="edit-qna" data-id="${esc(item._id)}">Edit</button>`}<button class="btn light small" data-action="${q ? "delete-quiz" : "delete-set"}" data-id="${esc(item._id)}" aria-label="Delete ${esc(title)}" title="Delete ${esc(title)}" style="color:#b42318">🗑</button></div></div></article>`; }
function homeView() { const total = state.quizzes.reduce((n,q)=>n+(q.quizes?.length||0),0)+state.sets.reduce((n,s)=>n+(s.questions?.length||0),0); return `<section class="page-head"><div><div class="eyebrow">A calmer way to study</div><h1>Make time for<br>what you’re learning.</h1><p>Your study space is ready. Build a quiz, practice recall, and keep the tricky bits in view.</p></div><button class="btn" data-action="open-quiz-create">＋ Create a quiz</button></section><section class="stats"><div class="stat" style="--tint:#e6f2d7"><div class="stat-label">QUIZ COLLECTION</div><div class="stat-value">${state.quizzes.length}</div><div class="stat-note">sets ready to practice</div></div><div class="stat" style="--tint:#e9e4ff"><div class="stat-label">OPEN RESPONSE</div><div class="stat-value">${state.sets.length}</div><div class="stat-note">topics in your Q&A library</div></div><div class="stat" style="--tint:#ffe7db"><div class="stat-label">QUESTIONS TO REVIEW</div><div class="stat-value">${state.mistakes.length}</div><div class="stat-note">missed questions saved for you</div></div></section><div class="section-head"><div><h2>Your library</h2><p>${total} questions across your study sets</p></div><div class="tools"><button class="btn light small" data-action="open-qna-create">＋ Q&A set</button></div></div><div class="library">${[...state.quizzes.map(i=>card(i,"quiz")),...state.sets.map(i=>card(i,"qna"))].join("") || `<div class="empty"><b>Your library starts here</b>Create a quiz or Q&A set from your notes, a PDF, or a few questions.</div>`}</div><div class="section-head"><div><h2>Pick up where you left off</h2><p>Short practice sessions add up.</p></div><a href="/practice" class="subtle" data-view="review">Review missed questions →</a></div>${state.mistakes.length ? `<div class="help-card"><h3>${state.mistakes.length} ${state.mistakes.length === 1 ? "question needs" : "questions need"} another look</h3><p>Revisit the ones you missed. Once you answer one correctly, it leaves your review list.</p><a class="btn" href="/practice" data-view="review" style="display:inline-block;margin-top:16px;text-decoration:none">Start a review</a></div>` : `<div class="panel"><h2>Clear review list</h2><p>Missed quiz questions will show up here automatically, ready for another attempt.</p></div>`}`; }
function reviewView() { return `<section class="page-head"><div><div class="eyebrow">Build it back, one question at a time</div><h1>Review & remember.</h1><p>Questions you missed in a quiz stay here until you get them right.</p></div>${state.mistakes.length ? `<button class="btn" data-action="start-review">Start review · ${state.mistakes.length}</button>` : ""}</section><div class="section-head"><div><h2>Needs another look</h2><p>${state.mistakes.length} active ${state.mistakes.length === 1 ? "question" : "questions"}</p></div></div>${state.mistakes.length ? `<div class="library" style="grid-template-columns:1fr">${state.mistakes.map(m=>`<article class="mistake-item"><div><h3>${esc(m.question)}</h3><p>Missed ${m.wrongCount} ${m.wrongCount === 1 ? "time" : "times"} · last practiced ${new Date(m.lastWrongAt).toLocaleDateString()}</p></div><button class="btn light small" data-action="remove-mistake" data-id="${esc(m._id)}">Remove</button></article>`).join("")}</div>`:`<div class="empty"><b>Nothing to review right now</b>Any quiz question you miss will be saved here for practice.</div>`}`; }
function qnaView() { return `<section class="page-head"><div><div class="eyebrow">Practice explaining, not just recognizing</div><h1>Say it in your own words.</h1><p>Build open response sets from your notes, then get thoughtful scoring on each answer.</p></div><button class="btn" data-action="open-qna-create">＋ New Q&A set</button></section><div class="section-head"><div><h2>Your Q&A sets</h2><p>${state.sets.length} sets · your attempts are saved in the history for each set</p></div></div><div class="library">${state.sets.map(s=>`<article class="study-card"><div class="card-top"><span class="tag purple">▤ Open response</span><span class="card-menu">${esc(s.subject)}</span></div><h3>${esc(s.title)}</h3><p>${s.questions?.length||0} questions · ${esc(s.subject)}</p><div class="card-foot"><span class="card-meta">Q&A SET</span><div class="card-actions"><button class="btn small" data-action="start-qna" data-id="${esc(s._id)}">Practice</button><button class="btn light small" data-action="view-qna" data-id="${esc(s._id)}">View Q&A</button><button class="btn light small" data-action="edit-qna" data-id="${esc(s._id)}">Edit</button><button class="btn light small" data-action="export-qna-json" data-id="${esc(s._id)}">Export JSON</button><button class="btn light small" data-action="qna-history" data-id="${esc(s._id)}">History</button><button class="btn light small" data-action="delete-set" data-id="${esc(s._id)}">Delete</button></div></div></article>`).join("") || `<div class="empty"><b>No Q&A sets yet</b>Create your first open response set from text, PDF, or manual questions.</div>`}</div>`; }
function modalMarkup() { if (state.modal === "quiz-create") return quizCreateModal(); if (state.modal === "qna-create") return qnaCreateModal(); if (state.modal === "qna-edit") return qnaEditModal(); if (state.modal === "qna-view") return qnaViewModal(); if (state.modal === "quiz") return quizModal(); if (state.modal === "qna-practice") return qnaPracticeModal(); if (state.modal === "history") return historyModal(); return ""; }
function quizCreateModal() { const manual = state.quizMode === "manual"; return `<div class="overlay" data-action="overlay-close"><section class="dialog wide" role="dialog" aria-modal="true"><div class="dialog-head"><div><h2>Create a quiz</h2><p>Turn your study material into a focused practice set.</p></div><button class="icon-btn" data-action="close">×</button></div><div class="split"><div class="panel"><div class="mode-tabs"><button class="${state.quizMode === "text" ? "active" : ""}" data-action="quiz-mode" data-mode="text">Paste notes</button><button class="${state.quizMode === "pdf" ? "active" : ""}" data-action="quiz-mode" data-mode="pdf">Upload PDF</button><button class="${manual ? "active" : ""}" data-action="quiz-mode" data-mode="manual">Manual / JSON</button></div><form id="quiz-form"><div class="form-grid"><div class="field"><label>QUIZ TITLE</label><input name="title" required placeholder="e.g. Cell biology review"></div><div class="field"><label>SUBJECT</label><input name="subject" required placeholder="e.g. Biology"></div><div class="field"><label>NUMBER OF QUESTIONS</label><input name="numberOfQuestions" type="number" min="1" max="100" value="10"></div>${manual ? `<div class="field full"><label>QUESTIONS AS JSON</label><textarea name="quizes" placeholder='[{"question":"What is...","option1":"...","option2":"...","option3":"...","option4":"...","correctOption":1}]' required></textarea></div>` : state.quizMode === "pdf" ? `<div class="field full"><label>PDF FILE</label><input name="pdf_file" type="file" accept="application/pdf" required></div>` : `<div class="field full"><label>STUDY NOTES</label><textarea name="text" placeholder="Paste a chapter, notes, or lesson transcript…" required></textarea></div>`}</div><div class="form-actions"><button class="btn" type="submit">Create quiz ↗</button><button class="btn light" type="button" data-action="close">Cancel</button></div><div class="notice" id="quiz-notice"></div></form></div><aside><div class="help-card"><h3>Study, your way</h3><p>Quiz questions are generated from your source. Missed answers are saved automatically, so you can revisit them later.</p></div><div class="feature-list"><div class="feature"><i>✦</i><span>Generate a quiz from notes or a PDF</span></div><div class="feature"><i>▤</i><span>Import questions from JSON or write your own</span></div><div class="feature"><i>↻</i><span>Track missed questions for review</span></div></div></aside></div></section></div>`; }
function qnaCreateModal() { const manual = state.qnaMode === "manual", json = state.qnaMode === "json"; return `<div class="overlay" data-action="overlay-close"><section class="dialog wide" role="dialog" aria-modal="true"><div class="dialog-head"><div><h2>Build a Q&A set</h2><p>Practice recall by putting the idea into your own words.</p></div><button class="icon-btn" data-action="close">×</button></div><div class="split"><div class="panel"><div class="mode-tabs"><button class="${state.qnaMode === "text" ? "active" : ""}" data-action="qna-mode" data-mode="text">From notes</button><button class="${state.qnaMode === "pdf" ? "active" : ""}" data-action="qna-mode" data-mode="pdf">From PDF</button><button class="${json ? "active" : ""}" data-action="qna-mode" data-mode="json">Upload JSON</button><button class="${manual ? "active" : ""}" data-action="qna-mode" data-mode="manual">Write questions</button></div><form id="qna-form"><div class="form-grid"><div class="field"><label>SET TITLE${json ? " (OPTIONAL IF IN JSON)" : ""}</label><input name="title" ${json ? "" : "required"} placeholder="e.g. The nervous system"></div><div class="field"><label>SUBJECT${json ? " (OPTIONAL IF IN JSON)" : ""}</label><input name="subject" ${json ? "" : "required"} placeholder="e.g. Biology"></div>${manual ? `<div class="field full"><label>QUESTIONS (one per line)</label><textarea name="questions" placeholder="Question: What does the cerebellum do?\nAnswer: It coordinates balance and movement." required></textarea></div>` : json ? `<div class="field full"><label>JSON FILE</label><input name="json_file" type="file" accept=".json,application/json" required><p class="muted">Use an array of question objects, or an object with a questions array. Each question needs question and answer fields. You can include title and subject in the object.</p><a class="btn light small" href="/samples/qna-sample.json" download>↓ Download sample JSON</a></div>` : `<div class="field"><label>NUMBER OF QUESTIONS</label><input name="numberOfQuestions" type="number" min="1" max="100" value="8"></div>${state.qnaMode === "pdf" ? `<div class="field full"><label>PDF FILE</label><input name="pdf_file" type="file" accept="application/pdf" required></div>` : `<div class="field full"><label>STUDY NOTES</label><textarea name="text" placeholder="Paste notes or reading material…" required></textarea></div>`}`}</div><div class="form-actions"><button class="btn" type="submit">Create Q&A set ↗</button><button class="btn light" type="button" data-action="close">Cancel</button></div><div class="notice" id="qna-notice"></div></form></div><aside><div class="help-card"><h3>Recall builds memory</h3><p>Answer by typing or speaking. Each response receives a score and feedback.</p></div></aside></div></section></div>`; }
function quizModal() { const q = state.quiz?.quizes?.[state.qi]; const total = state.quiz?.quizes?.length || 0; if (state.quizFinished || !q) return `<div class="overlay"><section class="dialog"><div class="dialog-head"><div><h2>Quiz complete</h2><p>${esc(state.quiz?.title)}</p></div><button class="icon-btn" data-action="close">×</button></div><div class="score-hero"><strong>${state.quizWrong.length === 0 ? "★" : total - state.quizWrong.length}</strong><span>${state.quizWrong.length === 0 ? "Perfect round" : `of ${total} questions answered correctly`}</span></div><div class="space"></div><p class="muted" style="font-size:12px">${state.quizWrong.length ? `${state.quizWrong.length} missed question${state.quizWrong.length===1?"":"s"} ${state.quizWrong.length===1?"has":"have"} been added to your review list.` : "Everything correct. Nice work."}</p><div class="form-actions"><button class="btn" data-action="close">Done</button></div></section></div>`; return `<div class="overlay"><section class="dialog"><div class="dialog-head"><div><div class="eyebrow">${esc(state.quiz.subject)} · QUESTION ${state.qi+1} OF ${total}</div><h2>${esc(state.quiz.title)}</h2></div><button class="icon-btn" data-action="quit-quiz">×</button></div><div class="quiz-progress"><span style="width:${state.qi/total*100}%"></span></div><h3 class="question-text">${esc(q.question)}</h3><div class="question-list">${[1,2,3,4].map((n,i)=>`<button class="q-option ${state.selected===n?"selected":""}" data-action="quiz-select" data-option="${n}"><span class="option-key">${String.fromCharCode(65+i)}</span>${esc(q[`option${n}`])}</button>`).join("")}</div><div class="quiz-bottom"><span class="subtle">Choose the best answer</span><button class="btn" data-action="quiz-next" ${state.selected===null?"disabled":""}>${state.qi === total-1 ? "Finish quiz" : "Next question →"}</button></div></section></div>`; }
function qnaPracticeModal() { const q = state.qna?.questions?.[state.qIndex]; const total = state.qna?.questions?.length || 0; if (!q) return `<div class="overlay"><section class="dialog"><div class="dialog-head"><div><h2>Session complete</h2><p>${esc(state.qna?.title)}</p></div><button class="icon-btn" data-action="close">×</button></div><div class="score-hero"><strong>${state.qResults?.length ? (state.qResults.reduce((s,r)=>s+r,0)/state.qResults.length).toFixed(1) : "—"}<small style="font-size:16px">/10</small></strong><span>average score across ${state.qResults?.length||0} answers</span></div><div class="form-actions"><button class="btn" data-action="close">Back to sets</button></div></section></div>`; const result=state.qResult; return `<div class="overlay"><section class="dialog"><div class="dialog-head"><div><div class="eyebrow">${esc(state.qna.subject)} · ${state.qIndex+1} OF ${total}</div><h2>${esc(state.qna.title)}</h2></div><button class="icon-btn" data-action="quit-qna">×</button></div><div class="quiz-progress"><span style="width:${state.qIndex/total*100}%"></span></div><h3 class="question-text">${esc(q.question)}</h3>${result ? `<div class="score-hero"><strong>${result.score}<small style="font-size:16px">/10</small></strong><span>${esc(result.feedback||"Good effort.")}</span></div><div class="answer-box"><h4>Reference answer</h4><p>${esc(q.answer)}</p></div>${result.missing?.length?`<div class="answer-box"><h4>Ideas to revisit</h4><p>${result.missing.map(esc).join(" · ")}</p></div>`:""}<div class="quiz-bottom"><span class="subtle">${state.qIndex+1} / ${total}</span><button class="btn" data-action="qna-next">${state.qIndex===total-1?"Finish session":"Next question →"}</button></div>`:`<textarea class="qna-answer" id="qna-answer" placeholder="Explain what you remember…"></textarea><div class="row" style="margin-top:10px"><button class="btn light small" data-action="speak">🎙 Speak</button><button class="btn" data-action="score-qna" style="margin-left:auto">Check my answer</button></div>`}</section></div>`; }
function historyModal() { const rows=state.history||[]; return `<div class="overlay" data-action="overlay-close"><section class="dialog"><div class="dialog-head"><div><h2>Practice history</h2><p>${esc(state.historyTitle||"")}</p></div><button class="icon-btn" data-action="close">×</button></div><div class="history-list">${rows.map(a=>`<article class="history-item"><strong>${esc(a.question)} <span class="tag">${a.score??"—"}/10</span></strong><p>${esc(a.feedback||a.userAnswer)}</p><span class="subtle">${new Date(a.createdAt).toLocaleString()}</span></article>`).join("")||`<div class="empty">No attempts yet. Your practice sessions will appear here.</div>`}</div></section></div>`; }
function qnaEditModal() { const set=state.editingSet; return `<div class="overlay"><section class="dialog wide" role="dialog" aria-modal="true"><div class="dialog-head"><div><h2>Edit Q&A set</h2><p>Update the set details and revise its questions or reference answers.</p></div><button class="icon-btn" data-action="close">×</button></div><form id="qna-edit-form"><div class="form-grid"><div class="field"><label>SET TITLE</label><input name="title" required value="${esc(set.title)}"></div><div class="field"><label>SUBJECT</label><input name="subject" required value="${esc(set.subject)}"></div></div><div class="section-head"><div><h2>Questions</h2><p>Edits apply to this set immediately after saving.</p></div><button class="btn light small" type="button" data-action="edit-qna-add">＋ Add question</button></div><div class="question-list">${state.editQuestions.map((q,i)=>`<div class="panel" style="padding:15px"><div class="field"><label>QUESTION ${i+1}</label><textarea name="question-${i}" required style="min-height:70px">${esc(q.question)}</textarea></div><div class="field" style="margin-top:10px"><label>REFERENCE ANSWER</label><textarea name="answer-${i}" required style="min-height:90px">${esc(q.answer)}</textarea></div><div class="field" style="margin-top:10px"><label>KEYWORDS</label><input name="keywords-${i}" value="${esc(Array.isArray(q.keywords)?q.keywords.join(", "):"")}" placeholder="e.g. memory, learning, recall"><p class="muted">Separate keywords with commas. Add, edit, or remove them here.</p></div><div class="row" style="justify-content:flex-end;margin-top:9px"><button class="btn light small" type="button" data-action="edit-qna-remove" data-index="${i}">Remove question</button></div></div>`).join("")}</div><div class="form-actions"><button class="btn" type="submit">Save changes</button><button class="btn light" type="button" data-action="close">Cancel</button></div><div class="notice" id="qna-edit-notice"></div></form></section></div>`; }
function render() { const app=$("#app"); if (!app) return; app.innerHTML=shell(state.view === "home" ? homeView() : state.view === "qna" ? qnaView() : reviewView()); document.title = `${state.view === "home" ? "Overview" : state.view === "qna" ? "Q&A Practice" : "Review"} · Studyroom`; }
function navigate(view, href) { state.view=view; history.pushState({},"",href); render(); window.scrollTo(0,0); }
function openQuiz(id) { const quiz=state.quizzes.find(q=>q._id===id); if (!quiz) return; state.quiz=quiz; state.qi=0; state.selected=null; state.quizWrong=[]; state.quizFinished=false; state.modal="quiz"; render(); }
function answerQuiz() { const q=state.quiz.quizes[state.qi], selected=state.selected; if (selected !== q.correctOption) state.quizWrong.push({...q,selectedOption:selected}); if (state.qi < state.quiz.quizes.length-1) { state.qi++; state.selected=null; state.modal="quiz"; render(); return; } state.quizFinished=true; state.modal="quiz"; render(); if (state.quizWrong.length) api("/api/v1/mistakes",{method:"POST",headers:{"x-user-id":uid},body:JSON.stringify({quizId:state.quiz._id,questions:state.quizWrong})}).then(refresh).catch(()=>{}); }
document.addEventListener("click", async e => { const link=e.target.closest("[data-view]"); if(link){e.preventDefault();navigate(link.dataset.view,link.getAttribute("href")||"/");return;} const el=e.target.closest("[data-action]");if(!el)return;const a=el.dataset.action;try{if(a==="toggle-sidebar"){state.sidebarCollapsed=!state.sidebarCollapsed;localStorage.setItem("studyroom-sidebar-collapsed",String(state.sidebarCollapsed));render();}else if(a==="refresh"){await refresh();toast("Study space refreshed");}else if(a==="open-quiz-create"){state.quizMode="text";state.modal="quiz-create";render();}else if(a==="open-qna-create"){state.qnaMode="text";state.modal="qna-create";render();}else if(a==="close"){state.modal=null;render();}else if(a==="overlay-close"&&e.target===el){state.modal=null;render();}else if(a==="quiz-mode"){state.quizMode=el.dataset.mode;render();}else if(a==="qna-mode"){state.qnaMode=el.dataset.mode;render();}else if(a==="start-quiz"){openQuiz(el.dataset.id);}else if(a==="quiz-select"){state.selected=Number(el.dataset.option);render();}else if(a==="quiz-next"){answerQuiz();}else if(a==="quit-quiz"){state.modal=null;render();}else if(a==="delete-quiz"){if(confirm("Delete this quiz?")){await api(`/api/v1/quiz/${el.dataset.id}`,{method:"DELETE"});await refresh();toast("Quiz deleted");}}else if(a==="delete-set"){if(confirm("Delete this Q&A set and its history?")){await api(`/api/v1/qna/${el.dataset.id}`,{method:"DELETE"});await refresh();toast("Q&A set deleted");}}else if(a==="start-qna"){state.qna=await api(`/api/v1/qna/${el.dataset.id}`);state.qIndex=0;state.qResult=null;state.qResults=[];state.modal="qna-practice";render();}else if(a==="quit-qna"){state.modal=null;render();}else if(a==="qna-next"){state.qResults.push(state.qResult.score);state.qIndex++;state.qResult=null;render();}else if(a==="score-qna"){const answer=$("#qna-answer")?.value.trim();if(!answer){toast("Write or record an answer first",true);return;}el.disabled=true;const result=await api(`/api/v1/qna/${state.qna._id}/score`,{method:"POST",headers:{"x-user-id":uid},body:JSON.stringify({questionIndex:state.qIndex,userAnswer:answer})});state.qResult=result;render();}else if(a==="speak"){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast("Speech input is not available in this browser",true);return;}const recog=new SR();recog.lang="en-US";recog.onresult=ev=>{$("#qna-answer").value+=` ${ev.results[0][0].transcript}`.trim();};recog.start();toast("Listening…");}else if(a==="qna-history"){state.historyTitle=state.sets.find(s=>s._id===el.dataset.id)?.title;state.history=await api(`/api/v1/qna/${el.dataset.id}/attempts`,{headers:{"x-user-id":uid}});state.modal="history";render();}else if(a==="start-review"){if(state.mistakes.length){state.reviewQueue=state.mistakes.map(m=>m._id).sort(()=>Math.random()-.5);state.reviewIndex=0;state.reviewHits=0;await reviewQuestion();}}else if(a==="remove-mistake"){await api(`/api/v1/mistakes/${el.dataset.id}`,{method:"DELETE",headers:{"x-user-id":uid}});await refresh();toast("Removed from review");}else if(a==="review-pick"){state.reviewSelected=Number(el.dataset.option);renderReviewModal();}else if(a==="review-check"){await checkReview();}else if(a==="review-next"){state.reviewIndex++;if(state.reviewIndex>=state.reviewQueue.length){state.modal="review-done";renderReviewModal();await refresh();}else await reviewQuestion();}else if(a==="review-done-close"){state.modal=null;render();}else if(a==="review-quit"){state.modal=null;render();}}catch(err){toast(err.message||"Something went wrong",true);}});
document.addEventListener("submit",async e=>{if(e.target.id==="quiz-form"){e.preventDefault();const form=e.target,fd=new FormData(form),mode=state.quizMode;const title=fd.get("title"),subject=fd.get("subject"),numberOfQuestions=Number(fd.get("numberOfQuestions"));let path,body;if(mode==="pdf"){path="/api/v1/quiz/pdf";body=new FormData();body.append("title",title);body.append("subject",subject);body.append("numberOfQuestions",numberOfQuestions);body.append("pdf_file",fd.get("pdf_file"));}else if(mode==="manual"){path="/api/v1/quiz/json";try{body=JSON.stringify({title,subject,quizes:JSON.parse(fd.get("quizes"))});}catch{ $("#quiz-notice").textContent="Please enter valid quiz JSON.";return;}}else{path="/api/v1/quiz/text";body=JSON.stringify({title,subject,text:fd.get("text"),numberOfQuestions});}const submit=form.querySelector('[type="submit"]');submit.disabled=true;submit.textContent="Creating…";try{await api(path,{method:"POST",body});state.modal=null;await refresh();toast("Your quiz is ready");}catch(err){$("#quiz-notice").textContent=err.message;submit.disabled=false;submit.textContent="Create quiz ↗";}}if(e.target.id==="qna-form"){e.preventDefault();const form=e.target,fd=new FormData(form),mode=state.qnaMode;let path,body;if(mode==="manual"){const lines=String(fd.get("questions")).split(/\r?\n/).map(s=>s.trim()).filter(Boolean);const questions=[];for(let i=0;i<lines.length;i+=2){const q=lines[i].replace(/^question\s*:\s*/i,"").trim(),answer=(lines[i+1]||"").replace(/^answer\s*:\s*/i,"").trim();if(q&&answer)questions.push({question:q,answer});}if(!questions.length){$("#qna-notice").textContent="Add question and answer lines in pairs.";return;}path="/api/v1/qna/manual";body=JSON.stringify({title:fd.get("title"),subject:fd.get("subject"),questions});}else if(mode==="json"){const file=fd.get("json_file");let parsed;try{parsed=JSON.parse(await file.text());}catch{$("#qna-notice").textContent="The selected file is not valid JSON.";return;}const questions=Array.isArray(parsed)?parsed:parsed?.questions;if(!Array.isArray(questions)||!questions.length){$("#qna-notice").textContent="JSON must contain a non-empty questions array.";return;}if(questions.some(q=>!q||typeof q.question!=="string"||!q.question.trim()||typeof q.answer!=="string"||!q.answer.trim())){$("#qna-notice").textContent="Every question needs non-empty question and answer fields.";return;}const title=String(fd.get("title")||parsed.title||"").trim(),subject=String(fd.get("subject")||parsed.subject||"").trim();if(!title||!subject){$("#qna-notice").textContent="Enter a title and subject, or include them in the JSON object.";return;}path="/api/v1/qna/manual";body=JSON.stringify({title,subject,questions:questions.map(q=>({question:q.question.trim(),answer:q.answer.trim(),...(Array.isArray(q.keywords)?{keywords:q.keywords.filter(k=>typeof k==="string").map(k=>k.trim()).filter(Boolean)}:{})}))});}else if(mode==="pdf"){path="/api/v1/qna/pdf";body=new FormData();body.append("title",fd.get("title"));body.append("subject",fd.get("subject"));body.append("numberOfQuestions",fd.get("numberOfQuestions"));body.append("pdf_file",fd.get("pdf_file"));}else{path="/api/v1/qna/text";body=JSON.stringify({title:fd.get("title"),subject:fd.get("subject"),text:fd.get("text"),numberOfQuestions:Number(fd.get("numberOfQuestions"))});}const submit=form.querySelector('[type="submit"]');submit.disabled=true;submit.textContent="Building…";try{await api(path,{method:"POST",body});state.modal=null;await refresh();toast("Your Q&A set is ready");}catch(err){$("#qna-notice").textContent=err.message;submit.disabled=false;submit.textContent="Create Q&A set ↗";}}});
window.addEventListener("popstate",()=>{state.view=location.pathname==="/qna"?"qna":location.pathname==="/practice"?"review":"home";state.modal=null;render();});
async function reviewQuestion(){const m=state.mistakes.find(item=>item._id===state.reviewQueue[state.reviewIndex]);if(!m){state.modal="review-done";renderReviewModal();return;}state.reviewCurrent=m;const opts=[1,2,3,4].sort(()=>Math.random()-.5);state.reviewOptions=opts;state.reviewSelected=null;state.reviewAnswered=false;state.modal="review";renderReviewModal();}
function renderReviewModal(){const app=$("#app");document.querySelector(".overlay")?.remove();if(state.modal==="review-done"){app.insertAdjacentHTML("beforeend",`<div class="overlay"><section class="dialog"><div class="dialog-head"><div><h2>Review complete</h2><p>You got ${state.reviewHits} of ${state.reviewQueue.length} right.</p></div></div><div class="score-hero"><strong>${state.reviewHits}/${state.reviewQueue.length}</strong><span>correct on this review</span></div><div class="form-actions"><button class="btn" data-action="review-done-close">Done</button></div></section></div>`);return;}const m=state.reviewCurrent;if(!m)return;const at=state.reviewOptions.indexOf(m.correctOption);const answered=state.reviewAnswered;const html=`<div class="overlay"><section class="dialog"><div class="dialog-head"><div><div class="eyebrow">QUESTION ${state.reviewIndex+1} OF ${state.reviewQueue.length} · MISSED ${m.wrongCount}×</div><h2>Review & remember</h2></div><button class="icon-btn" data-action="review-quit">×</button></div><h3 class="question-text">${esc(m.question)}</h3><div class="question-list">${state.reviewOptions.map((n,i)=>`<button class="q-option ${state.reviewSelected===n?"selected":""} ${answered&&n===m.correctOption?"correct":""} ${answered&&n===state.reviewSelected&&n!==m.correctOption?"incorrect":""}" data-action="review-pick" data-option="${n}" ${answered?"disabled":""}><span class="option-key">${String.fromCharCode(65+i)}</span>${esc(m[`option${n}`])}</button>`).join("")}</div>${answered?`<p class="notice">${state.reviewSelected===m.correctOption?"Correct — removed from your review list.":`Not quite. The answer was ${String.fromCharCode(65+at)}.`}</p>`:""}<div class="quiz-bottom"><span class="subtle">${m.wrongCount} past misses</span><button class="btn" data-action="${answered?"review-next":"review-check"}" ${!answered&&state.reviewSelected===null?"disabled":""}>${answered?(state.reviewIndex===state.reviewQueue.length-1?"Finish":"Next question →"):"Check answer"}</button></div></section></div>`;app.insertAdjacentHTML("beforeend",html);}
async function checkReview(){const m=state.reviewCurrent,correct=state.reviewSelected===m.correctOption;state.reviewAnswered=true;if(correct){state.reviewHits++;await api("/api/v1/mistakes/resolve",{method:"POST",headers:{"x-user-id":uid},body:JSON.stringify({mistakeId:m._id})});}else{await api("/api/v1/mistakes",{method:"POST",headers:{"x-user-id":uid},body:JSON.stringify({quizId:m.quizId,questions:[{question:m.question,option1:m.option1,option2:m.option2,option3:m.option3,option4:m.option4,correctOption:m.correctOption,selectedOption:state.reviewSelected}]})});}renderReviewModal();}
const oldRender=render;render=()=>{oldRender();if(state.modal?.startsWith("review"))renderReviewModal();};
refresh().catch(err=>{const app=$("#app");app.innerHTML=`<main class="main"><div class="empty"><b>Could not load your study space</b>${esc(err.message)}<br><button class="btn" onclick="location.reload()" style="margin-top:14px">Try again</button></div></main>`;});
function captureQnaEditDraft(){const form=$("#qna-edit-form");if(!form)return;state.editingSet={...state.editingSet,title:form.elements.title.value,subject:form.elements.subject.value};state.editQuestions=state.editQuestions.map((q,i)=>({...q,question:form.elements[`question-${i}`].value,answer:form.elements[`answer-${i}`].value,keywords:(form.elements[`keywords-${i}`].value||"").split(",").map(k=>k.trim()).filter(Boolean)}));}
document.addEventListener("click",async e=>{const el=e.target.closest('[data-action="edit-qna"],[data-action="edit-qna-add"],[data-action="edit-qna-remove"]');if(!el)return;try{if(el.dataset.action==="edit-qna"){state.editingSet=await api(`/api/v1/qna/${el.dataset.id}`);state.editQuestions=(state.editingSet.questions||[]).map(q=>({...q}));state.modal="qna-edit";render();}else{captureQnaEditDraft();if(el.dataset.action==="edit-qna-add")state.editQuestions.push({question:"",answer:"",keywords:[]});else state.editQuestions.splice(Number(el.dataset.index),1);render();}}catch(err){toast(err.message||"Could not open this Q&A set",true);}});
document.addEventListener("submit",async e=>{if(e.target.id!=="qna-edit-form")return;e.preventDefault();captureQnaEditDraft();const notice=$("#qna-edit-notice"),form=e.target;if(!state.editQuestions.length){notice.textContent="Keep at least one question in the set.";return;}if(state.editQuestions.some(q=>!q.question.trim()||!q.answer.trim())){notice.textContent="Each question and reference answer must contain text.";return;}const submit=form.querySelector('[type="submit"]');submit.disabled=true;submit.textContent="Saving…";try{await api(`/api/v1/qna/${state.editingSet._id}`,{method:"PUT",body:JSON.stringify({title:state.editingSet.title.trim(),subject:state.editingSet.subject.trim(),questions:state.editQuestions.map(q=>({question:q.question.trim(),answer:q.answer.trim(),...(Array.isArray(q.keywords)?{keywords:q.keywords}:{})}))})});state.modal=null;await refresh();toast("Q&A set updated");}catch(err){notice.textContent=err.message;submit.disabled=false;submit.textContent="Save changes";}});


// QNA_JSON_EXPORT
document.addEventListener("click", function (e) {
  const button = e.target.closest('[data-action="export-qna-json"]');
  if (!button) return;

  const set = state.sets.find(item => String(item._id) === button.dataset.id);
  if (!set) {
    alert("Q&A set not found. Please refresh the page.");
    return;
  }

  const data = {
    title: set.title || "",
    subject: set.subject || "",
    questions: set.questions || []
  };

  const blob = new Blob([JSON.stringify(data, null, 2)], {
    type: "application/json;charset=utf-8"
  });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = (set.title || "qna").replace(/[^a-z0-9_-]+/gi, "_") + ".json";
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
});


function qnaViewModal() {
  const set = state.viewingSet;
  if (!set) return "";
  return `<div class="overlay"><section class="dialog wide" role="dialog" aria-modal="true">
    <div class="dialog-head"><div><h2>Review Q&A</h2><p>${esc(set.title)} · ${esc(set.subject)} · ${(set.questions || []).length} questions</p></div><button class="icon-btn" data-action="close">×</button></div>
    <div class="question-list" style="max-height:65vh;overflow-y:auto">
      ${(set.questions || []).map((q,i) => `<article class="panel" style="padding:15px;margin-bottom:12px">
        <span class="tag purple">QUESTION ${i+1}</span><h3 style="margin:10px 0">${esc(q.question)}</h3>
        <div class="answer-box"><h4>Reference answer</h4><p>${esc(q.answer)}</p></div>
      </article>`).join("") || `<div class="empty">No questions in this set.</div>`}
    </div>
    <div class="form-actions"><button class="btn light" data-action="close">Close</button></div>
  </section></div>`;
}


// QNA_VIEW_MODE
document.addEventListener("click", async e => {
  const button = e.target.closest('[data-action="view-qna"]');
  if (!button) return;
  try {
    state.viewingSet = await api(`/api/v1/qna/${button.dataset.id}`);
    state.modal = "qna-view";
    render();
  } catch (err) {
    toast(err.message || "Could not open this Q&A set", true);
  }
});
